+    (e) => e.problems.some((p) => p.kind === 'family-collision'));
+
+  throws('an arbiter that is the drafter is refused, because it would judge its own output',
+    () => resolveRoles(JSON.parse(readFileSync(mapWith({
+      [ROLE_JOBS.drafter]: 'model-a',
